package com.bank.flink.cl;

import java.math.BigDecimal;

// A single changelog message.
class Change {
    enum Kind { INSERT, RETRACT, DELETE }

    private final Kind kind;
    private final boolean keyed;
    private final String key;
    private final BigDecimal value;

    Change(Kind kind, boolean keyed, String key, BigDecimal value) {
        this.kind = kind;
        this.keyed = keyed;
        this.key = key;
        this.value = value;
    }

    Kind getKind() { return kind; }
    boolean isKeyed() { return keyed; }

    @Override
    public String toString() {
        String sign = kind == Kind.RETRACT ? "-" : (kind == Kind.DELETE ? "DEL" : "+");
        return sign + "(" + key + "=" + value + ")";
    }
}
