package com.bank.flink.cl;

import java.math.BigDecimal;
import java.util.logging.Logger;

// APPEND-ONLY: a filter that emits only INSERTs, never revises output.
class AppendQuery {
    private static final Logger log = Logger.getLogger(AppendQuery.class.getName());

    private final BigDecimal threshold;

    AppendQuery(BigDecimal threshold) {
        this.threshold = threshold;
    }

    Change onTransaction(String account, BigDecimal amount) {
        if (amount.compareTo(threshold) > 0) {
            Change c = new Change(Change.Kind.INSERT, false, account, amount);
            log.info(() -> "APPEND-ONLY emit " + c);
            return c;
        }
        return null; // filtered out
    }
}
