package com.bank.flink.cl;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// RETRACT: running COUNT per account. On update, emit -old then +new.
class RetractAggregation {
    private static final Logger log = Logger.getLogger(RetractAggregation.class.getName());

    private final Map<String, Long> countByAccount = new HashMap<>();

    List<Change> onTransaction(String account) {
        List<Change> out = new ArrayList<>();
        boolean existed = countByAccount.containsKey(account);
        long oldCount = countByAccount.getOrDefault(account, 0L);
        long newCount = oldCount + 1;
        countByAccount.put(account, newCount);

        if (existed) {
            out.add(new Change(Change.Kind.RETRACT, false, account, BigDecimal.valueOf(oldCount)));
        }
        out.add(new Change(Change.Kind.INSERT, false, account, BigDecimal.valueOf(newCount)));
        out.forEach(c -> log.info(() -> "RETRACT-STREAM emit " + c));
        return out;
    }
}
