package com.bank.flink.cl;

import java.math.BigDecimal;
import java.util.logging.Logger;

// UPSERT (keyed): a CDC feed of balances. Each change is ONE keyed upsert,
// or a delete. No retraction pair needed because the key identifies the row.
class UpsertCdc {
    private static final Logger log = Logger.getLogger(UpsertCdc.class.getName());

    Change onBalanceChange(String account, BigDecimal newBalance) {
        Change c = new Change(Change.Kind.INSERT, true, account, newBalance); // upsert = keyed insert/update
        log.info(() -> "UPSERT-STREAM emit UPSERT(key=" + account + ", balance=" + newBalance + ")");
        return c;
    }

    Change onAccountClosed(String account) {
        Change c = new Change(Change.Kind.DELETE, true, account, null);
        log.info(() -> "UPSERT-STREAM emit DELETE(key=" + account + ")");
        return c;
    }
}
