package com.bank.flink.cl;

import java.util.logging.Logger;

// An append-only sink: it REJECTS retract/delete messages, mirroring how the
// Flink planner refuses an updating query into an append-only sink.
class AppendOnlySink {
    private static final Logger log = Logger.getLogger(AppendOnlySink.class.getName());

    void accept(Change c) {
        if (c.getKind() != Change.Kind.INSERT) {
            log.severe(() -> "AppendOnlySink REJECTS " + c
                    + " -> query changelog mode incompatible with sink");
            throw new UnsupportedOperationException("append-only sink cannot consume " + c.getKind());
        }
        log.info(() -> "AppendOnlySink accepted " + c);
    }
}
