package com.bank.flink.cl;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: all three changelog modes, plus a rejected mode mismatch.
public class ChangelogModeDemo {
    private static final Logger log = Logger.getLogger(ChangelogModeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new ClLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info(() -> "--- APPEND-ONLY (filter high-value txns) ---");
        AppendQuery append = new AppendQuery(new BigDecimal("500000"));
        append.onTransaction("SAV2001", new BigDecimal("600000"));
        append.onTransaction("CUR3001", new BigDecimal("250000")); // filtered

        log.info(() -> "--- RETRACT (running count per account) ---");
        RetractAggregation retract = new RetractAggregation();
        retract.onTransaction("SAV2001");
        retract.onTransaction("SAV2001"); // update -> retract + insert

        log.info(() -> "--- UPSERT (CDC balances, keyed) ---");
        UpsertCdc upsert = new UpsertCdc();
        upsert.onBalanceChange("SAV2001", new BigDecimal("1250"));
        upsert.onBalanceChange("SAV2001", new BigDecimal("1300")); // single keyed upsert
        upsert.onAccountClosed("CUR3001");

        log.info(() -> "--- MODE MISMATCH: retract output into append-only sink ---");
        AppendOnlySink sink = new AppendOnlySink();
        List<Change> retractChanges = retract.onTransaction("SAV2001"); // emits a RETRACT
        try {
            for (Change c : retractChanges) sink.accept(c);
        } catch (UnsupportedOperationException ex) {
            log.severe(() -> "Caught expected rejection: " + ex.getMessage());
        }
    }
}

// ─── Would be in ClLogFormatter.java in a real project ───
class ClLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
